)
SELECT jsonb_build_object('format','selqiro-account-public-profile-fence-20261123-v1',
 'stage','preflight','state',state,'recognized',state IN ('before','after'),'read_only',true,
 'account_rows_read',false,'account_rows_exported',false,
 'base_fingerprint',encode(sha256(convert_to(b::text,'UTF8')),'hex'),
 'target_fingerprint',encode(sha256(convert_to(t::text,'UTF8')),'hex'),
 'fence_verified',state='after') INTO observed FROM evaluated;
 IF observed->>'state' IS DISTINCT FROM 'before' THEN
  RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='ACCOUNT_PUBLIC_PROFILE_SCHEMA_MISMATCH';
 END IF;
END;
$profile_guard$;
-- Only public read eligibility; no state transition, row lock or repair-on-read.
CREATE FUNCTION account_lifecycle_private.account_is_available(p_account_user_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = pg_catalog
AS $account_available$
 SELECT EXISTS (
  SELECT 1
  FROM account_lifecycle_private.account_states AS s
  JOIN auth.users AS u ON u.id = s.account_user_id
  WHERE s.account_user_id = p_account_user_id
    AND s.state = 'active'
    AND s.revision > 0
    AND u.deleted_at IS NULL
    AND (u.banned_until IS NULL OR u.banned_until <= pg_catalog.statement_timestamp())
    AND (u.created_at IS NULL OR pg_catalog.isfinite(u.created_at))
 );
$account_available$;
REVOKE ALL ON FUNCTION account_lifecycle_private.account_is_available(uuid)
 FROM PUBLIC, anon, authenticated, service_role;

-- Canonical selected candidate remains unchanged; eligibility is applied afterwards.
CREATE OR REPLACE FUNCTION public.get_store_by_slug(store_slug_input text)
RETURNS TABLE(identity_profile_id uuid,identity_id uuid,identity_type text,business_account_id uuid,
 display_name text,slug text,bio text,avatar_url text,banner_url text,banner_dominant_color text,
 contact_phone text,contact_email text,website_url text,address_text text,city text,country text,
 lat double precision,lng double precision,location_visibility text,legacy_user_id uuid,is_premium boolean)
LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public,auth,pg_temp AS $privacy$
 WITH selected AS MATERIALIZED(
  SELECT ip.id identity_profile_id,i.id identity_id,i.type identity_type,i.business_account_id,
   ip.display_name,ip.slug,coalesce(ip.bio,p.bio) bio,profile_media_private.slot_url(i.id,'avatar') avatar_url,
   profile_media_private.slot_url(i.id,'cover') banner_url,coalesce(ip.banner_dominant_color,p.banner_dominant_color) banner_dominant_color,
   ip.contact_phone,ip.contact_email,ip.website_url,ip.address_text,ip.city,ip.country,
   ip.lat,ip.lng,ip.location_visibility,i.user_id legacy_user_id,coalesce(p.is_premium,false) is_premium,
   CASE WHEN i.type='private' THEN i.user_id ELSE business.owner_user_id END block_account_id,
   i.status identity_status,business.status business_status
  FROM public.identity_profiles ip JOIN public.identities i ON i.id=ip.identity_id
  LEFT JOIN public.profiles p ON p.id=i.user_id
  LEFT JOIN public.business_accounts business ON business.id=i.business_account_id
  WHERE ip.slug=store_slug_input OR p.store_slug=store_slug_input
  ORDER BY CASE WHEN ip.slug=store_slug_input THEN 0 ELSE 1 END LIMIT 1
 )
 SELECT s.identity_profile_id,s.identity_id,s.identity_type,s.business_account_id,s.display_name,s.slug,s.bio,
 s.avatar_url,s.banner_url,s.banner_dominant_color,s.contact_phone,s.contact_email,s.website_url,
 CASE WHEN s.identity_type='business' AND s.location_visibility='exact' THEN s.address_text ELSE NULL END,
 CASE WHEN s.location_visibility IN('city','exact') THEN s.city ELSE NULL END,
 CASE WHEN s.location_visibility IN('city','exact') THEN s.country ELSE NULL END,
 CASE WHEN s.identity_type='business' AND s.location_visibility='exact' THEN s.lat ELSE NULL END,
 CASE WHEN s.identity_type='business' AND s.location_visibility='exact' THEN s.lng ELSE NULL END,
 CASE WHEN s.identity_type='business' AND s.location_visibility='exact' THEN 'exact'
      WHEN s.location_visibility IN('city','exact') THEN 'city' ELSE 'hidden' END,
 s.legacy_user_id,s.is_premium FROM selected s
 WHERE s.identity_type IN ('private','business')
 AND account_lifecycle_private.account_is_available(s.block_account_id)
 AND s.identity_status='active' AND (s.identity_type='private' OR s.business_status='active')
 AND NOT EXISTS(SELECT 1 FROM public.user_blocks b WHERE auth.uid() IS NOT NULL
 AND ((b.blocker_id=auth.uid() AND b.blocked_id=s.block_account_id)
 OR (b.blocked_id=auth.uid() AND b.blocker_id=s.block_account_id)));
$privacy$;

DO $profile_guard$
DECLARE observed jsonb;
BEGIN
 -- Catalog only; no application/Auth/Storage rows.
WITH foundation_functions AS (
 SELECT COALESCE(jsonb_agg(jsonb_build_object(
  'name',n.nspname||'.'||p.proname,
  'arguments',COALESCE((SELECT jsonb_agg(format_type(a,NULL) ORDER BY ord) FROM unnest(p.proargtypes::oid[]) WITH ORDINALITY x(a,ord)),'[]'::jsonb),
  'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'language',l.lanname,
  'definer',p.prosecdef,'volatility',p.provolatile::text,'strict',p.proisstrict,'parallel',p.proparallel::text,'leakproof',p.proleakproof,
  'config_sha256',CASE WHEN p.proconfig IS NULL THEN NULL ELSE encode(sha256(convert_to(p.proconfig::text,'UTF8')),'hex') END,
  'definition_sha256',encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex'),
  'body_sha256',encode(sha256(convert_to(p.prosrc,'UTF8')),'hex'),'defaults',p.pronargdefaults<>0,
  'grants',COALESCE((SELECT jsonb_agg(jsonb_build_object('role',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type)
   FROM aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a),'[]'::jsonb)) ORDER BY n.nspname,p.proname,p.oid),'[]'::jsonb) value
 FROM (SELECT p.* FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname='account_lifecycle_private' AND p.proname<>'account_is_available') OR (n.nspname='public' AND p.proname='get_my_account_state_v1') ORDER BY n.nspname,p.proname,p.oid LIMIT 4) p
